var specialArray = function(nums) {
    nums.sort((a, b) => b - a);
    const n = nums.length;
    for (let x = 1; x <= n; ++x) {
        if (nums[x - 1] >= x && (x === n || nums[x] < x)) {
            return x;
        }
    }
    return -1;
};
